import java.io.*;
import java.util.*;

public class Unlucky {
    private static final int TARGET_SUM = 13;

    public static void main(String[] args) throws IOException{
        Scanner s = new Scanner(new File("unlucky.dat"));
        int numSets = s.nextInt();
        s.nextLine();
        
        for(int i = 1; i <= numSets; i++){
            String num = s.nextLine();
            int forwardSum = 0;;
            int backwardSum = 0;
            int pos = 0;
            while(pos < num.length() && forwardSum < 13){
                forwardSum += num.charAt(pos) - '0';
                pos++;
            }
            if(forwardSum == TARGET_SUM){
                pos = num.length() - 1;
                while( pos >= 0 && backwardSum < TARGET_SUM){
                    backwardSum += num.charAt(pos) - '0';
                    pos--;
                }
            }
            if( forwardSum == TARGET_SUM && backwardSum == TARGET_SUM)
                System.out.println("UNLUCKY");
            else
                System.out.println("NOT UNLUCKY");
        }
    }
}

import java.util.*;
import java.io.*;
import static java.lang.System.*;


public class Valet {

	public static void main(String args[]) throws IOException
	{

		Scanner kb = new Scanner(new File("valet.dat"));

		int times = 0; 
		int count = kb.nextInt();
		String ff = kb.nextLine();
		while(times < count) {
			times++;
			String [] s = kb.nextLine().trim().split(" ");
			String cars = s[0];
			out.println(cars);			
			for(int i=1; i<s.length; i++) {
				
				int numCars = cars.length();
				int index = cars.indexOf(s[i]);
				String q = "";
				if(index <= numCars / 2) {
					for(int j = 0; j<index; j++) {
						q = cars.charAt(j) + q;
					}
					cars = q + cars.substring(index+1);
					numCars = cars.length();
											
				}
				else
				{
					for(int j = numCars-1; j>index; j--) {
						q += cars.charAt(j);
					}
					cars = cars.substring(0,index) + q;
					numCars = cars.length();
				}
				if(cars.length() != 0)
					out.println(s[i] + " " + cars);
				else
					out.println(s[i] + " PARKING LOT EMPTY");
				
			}
			out.println();			
		}
	}	
}
